from itertools import combinations, product
import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        blocked = set(data.get("blocked", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        best_list = None
        for subset in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            chosen_ids = set(ids)
            if not mandatory <= chosen_ids or blocked & chosen_ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = {}
            for job in subset:
                events[job["start"]] = events.get(job["start"], 0) + 1
                events[job["end"]] = events.get(job["end"], 0) - 1
            active = 0
            if any((active := active + events[t]) > capacity
                   for t in sorted(events)):
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                (value == best_value and
                 (ids < best_ids if tie == "smallest" else ids > best_ids))):
                best_value, best_ids, best_list = value, ids, list(ids)
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_list, "value": best_value}
    return solve


def _ledger(data):
    def rounded(n, mode):
        if mode == "half_up":
            return (2 * n + 10000) // 20000
        return n // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)
    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(net * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    available = {}
    for name in names:
        available[name] = [-1] + sorted(row["version"] for row in packages[name])
    best = None
    best_install = None
    for values in product(*(available[name] for name in names)):
        versions = dict(zip(names, values))
        edges = {}
        valid = True
        for name, bounds in roots.items():
            version = versions[name]
            if version < bounds[0] or version > bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, version in versions.items():
            if version == -1:
                continue
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
            row = next(row for row in packages[name] if row["version"] == version)
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = versions[dep["name"]]
                if other < dep["min"] or other > dep["max"]:
                    valid = False
                    break
                deps.append(dep["name"])
            if not valid:
                break
            edges[name] = deps
        if not valid:
            continue
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if versions[name] == -1:
                valid = False
                break
            stack.extend(edges.get(name, []))
        if not valid or reachable != {n for n in names if versions[n] != -1}:
            continue
        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in reachable):
            continue
        vector = tuple(values)
        if best is None or vector < best:
            best = vector
            best_install = {n: versions[n] for n in names if versions[n] != -1}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 0 for node in range(data["n"])}
    for i, node in enumerate(required):
        bits[node] |= 1 << i
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], bits[data["source"]], data["coupons"])
    start_time = data["start"]
    distances = {start_state: start_time}
    queue = [(start_time, *start_state)]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], mask | bits[edge["v"]], remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


SOLVERS = {
    "component_01": _quota_solver(1, "smallest"),
    "component_02": _quota_solver(2, "smallest"),
    "component_03": _quota_solver(1, "largest"),
    "component_04": _quota_solver(2, "largest"),
    "component_05": _quota_solver(1, "smallest"),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _routes,
}
